function Require-File([string]$Path){$item=Get-Item -LiteralPath $Path -Force -ErrorAction Stop;if(($item.Attributes -band [IO.FileAttributes]::ReparsePoint)-ne 0 -or -not $item.PSIsContainer -and $item.Length -gt 134217728){throw "fresh source rejected: $Path"};return $item}
function Pin([string]$Path){$item=Require-File $Path;return [ordered]@{path=[IO.Path]::GetFullPath($item.FullName);bytes=$item.Length;sha256=(Get-FileHash -LiteralPath $item.FullName -Algorithm SHA256).Hash.ToLowerInvariant()}}
