$factoryPrefix=([IO.Path]::GetFullPath($factoryRoot)).TrimEnd('\')+'\';if(-not([IO.Path]::GetFullPath($runRoot).StartsWith($factoryPrefix,[StringComparison]::OrdinalIgnoreCase))){throw 'RunRoot must remain inside factory namespace'}
$frozen=Join-Path $control 'task-workload.ps1';$helper=Join-Path $Repo 'factory\pipeline\pilot-next-source-v1\windows-capture-v1\Sr0OwnedJobProcess-v15.cs';$parser=Join-Path $src 'receipt-parser-v4.ps1';$worker=Join-Path $src 'run-once-v4.ps1';$launcherHelper=Join-Path $src 'Sr0LauncherOwnedJobProcess-v4.cs';$collector=Join-Path $src 'collector-selfjob-v4.ps1';$coordinator=Join-Path $src 'coordinator-selfjob-v4.ps1';$wrapper=Join-Path $src 'launch-once-v4.vbs';$schedule=Join-Path $src 'schedule-once-v4.ps1'
