if($sources.workloadExe.sha256 -cne '7e749248800da8e6058b0b69ccbab2a5ce2e43a1a719475616da5e92936d930c'){throw 'WorkloadWin.exe immutable pin mismatch'};if($sources.rendererDll.sha256 -cne '7578cd5da8a6831900c66680c4b94f89e64b6b294623709817848b02219aeac2'){throw 'renderer immutable pin mismatch'};if($sources.presentMonExe.sha256 -cne 'b2a706bc6ad475749e3b7e3409263aa1e6906d45bdcf993f6dbc0f660188f1af'){throw 'PresentMon immutable pin mismatch'}
$plan=[ordered]@{schema='sr0-display-selfjob-v4-fresh-one-run';status='source-pin-plan';taskName=$task;tag=$task;base=[IO.Path]::GetFullPath($base);controlRoot=[IO.Path]::GetFullPath($control);factoryRoot=[IO.Path]::GetFullPath($factoryRoot);runRoot=[IO.Path]::GetFullPath($runRoot);manifestPath=(Join-Path $factoryRoot 'one-shot-manifest.json');lockPath=$lock;wscriptPath=$wscript;noActivate=$true;noResources=$true;runs=1;warmup=10;measure=60;rows=200;keyRate=10;deadlineSeconds=900;pollSeconds=1;aggregateJobMemoryLimitBytes=1073741824;memoryLimitFlags='0x200';killOnJobClose=$false;schedulePath=[IO.Path]::GetFullPath($schedule);sources=$sources;outputs=@('start-receipt.json','collector-receipt.json','coordinator-verdict.json','launcher-receipt.json','presentmon.csv','result-workload.txt');execution='root must run schedule-once-v4.ps1 with these explicit pins after controls pass'}
$parent=Split-Path -Parent ([IO.Path]::GetFullPath($OutputPath));if(-not([IO.Path]::GetFullPath($OutputPath).StartsWith($factoryPrefix,[StringComparison]::OrdinalIgnoreCase))){throw 'plan output must remain inside factory namespace'};if(Test-Path -LiteralPath $OutputPath){throw "fresh plan already exists: $OutputPath"};if(-not(Test-Path -LiteralPath $parent)){[IO.Directory]::CreateDirectory($parent)|Out-Null};$tmp="$OutputPath.$PID.$([guid]::NewGuid().ToString('N')).tmp";$stream=[IO.File]::Open($tmp,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::Read);try{$bytes=[Text.Encoding]::UTF8.GetBytes(($plan|ConvertTo-Json -Depth 16)+"`r`n");$stream.Write($bytes,0,$bytes.Length);$stream.Flush($true)}finally{$stream.Dispose()};[IO.File]::Move($tmp,$OutputPath);$plan|ConvertTo-Json -Depth 16
